/* Rebuild all mutable color and border-edge structures from the current grid. */
void rebuild_after_patch() {
    for (int color = 0; color <= M_FIXED; ++color) {
        cells_by_color[color].clear();
    }
    current_border_edges_tracker.clear();

    for (int r = 0; r < N_FIXED; ++r) {
        for (int c = 0; c < N_FIXED; ++c) {
            add_cell_to_color_ds(r, c, current_grid_state[r][c]);
        }
    }

    for (int r = 0; r < N_FIXED; ++r) {
        for (int c = 0; c < N_FIXED; ++c) {
            int color = current_grid_state[r][c];

            if (r == 0) current_border_edges_tracker.add_edge(0, color);
            if (r + 1 == N_FIXED) current_border_edges_tracker.add_edge(0, color);
            if (c == 0) current_border_edges_tracker.add_edge(0, color);
            if (c + 1 == N_FIXED) current_border_edges_tracker.add_edge(0, color);

            if (c + 1 < N_FIXED) {
                current_border_edges_tracker.add_edge(
                    color, current_grid_state[r][c + 1]);
            }
            if (r + 1 < N_FIXED) {
                current_border_edges_tracker.add_edge(
