/* Validate all ward components, the exterior zero component, and every adjacency. */
bool validate_patch_state() {
    for (int color = 1; color <= M_FIXED; ++color) {
        if (cells_by_color[color].empty()) return false;
        if (!check_region_connectivity_bfs(color)) return false;
    }

    if (!check_region_0_connectivity_full()) return false;

    for (int a = 0; a <= M_FIXED; ++a) {
        for (int b = a + 1; b <= M_FIXED; ++b) {
            bool present =
                current_border_edges_tracker.get_count(a, b) > 0;
            if (present != required_adjacencies.is_adj(a, b)) {
                return false;
            }
        }
    }
    return true;
}

/* Delete one exterior-attached connected branch after local witness filtering. */
bool try_delete_connected_patch(int start_r, int start_c,
                                int target_color, int requested_size) {
    std::vector<std::pair<int, int>> patch;
    bool in_patch[N_FIXED][N_FIXED] = {};

    patch.push_back({start_r, start_c});
    in_patch[start_r][start_c] = true;

    for (int index = 0;
         index < (int)patch.size() &&
         (int)patch.size() < requested_size;
         ++index) {
        int r = patch[index].first;
        int c = patch[index].second;

        int order[4] = {0, 1, 2, 3};
        for (int k = 3; k > 0; --k) {
            int p = rnd_gen.next_int(k + 1);
            int tmp = order[k];
            order[k] = order[p];
            order[p] = tmp;
        }

        for (int oi = 0;
             oi < 4 && (int)patch.size() < requested_size;
             ++oi) {
            int dir = order[oi];
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            if (!is_cell_on_grid(nr, nc)) continue;
            if (in_patch[nr][nc]) continue;
            if (current_grid_state[nr][nc] != target_color) continue;

            in_patch[nr][nc] = true;
            patch.push_back({nr, nc});
        }
    }

    if ((int)patch.size() < 2) return false;
    if ((int)patch.size() >=
        (int)cells_by_color[target_color].size()) {
        return false;
    }

    /*
     * Any neighbor exposed by deletion becomes adjacent to zero.
     * Such an edge is legal only if zero was already required to touch
     * that neighbor. This eliminates most impossible candidates cheaply.
     */
    for (const auto& cell : patch) {
        int r = cell.first;
        int c = cell.second;

        for (int k = 0; k < 4; ++k) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            if (!is_cell_on_grid(nr, nc)) continue;
            if (in_patch[nr][nc]) continue;

            int neighbor = current_grid_state[nr][nc];
            if (neighbor != target_color &&
                !required_adjacencies.is_adj(0, neighbor)) {
                return false;
            }
        }
    }

    /*
     * Do not remove the last witness of any required edge incident to
     * the target ward. Count only edges which are actually cut away.
     */
    int removed_edges[M_FIXED + 1][M_FIXED + 1] = {};
    for (const auto& cell : patch) {
        int r = cell.first;
        int c = cell.second;

        for (int k = 0; k < 4; ++k) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            int neighbor = is_cell_on_grid(nr, nc)
                               ? current_grid_state[nr][nc]
                               : 0;

            if (neighbor == target_color) continue;
            if (is_cell_on_grid(nr, nc) && in_patch[nr][nc]) continue;

            int a = std::min(target_color, neighbor);
            int b = std::max(target_color, neighbor);
            if (a != b) ++removed_edges[a][b];
        }
    }

    for (int a = 0; a <= M_FIXED; ++a) {
        for (int b = a + 1; b <= M_FIXED; ++b) {
            if (removed_edges[a][b] == 0) continue;
            if (!required_adjacencies.is_adj(a, b)) return false;
            if (current_border_edges_tracker.get_count(a, b)
                <= removed_edges[a][b]) {
                return false;
            }
        }
    }

    for (const auto& cell : patch) {
        current_grid_state[cell.first][cell.second] = 0;
    }

    rebuild_after_patch();
    if (validate_patch_state()) return true;

    for (const auto& cell : patch) {
        current_grid_state[cell.first][cell.second] = target_color;
    }
    rebuild_after_patch();
    return false;
}

